legend {
    color: var(--primary-light);
}

.form-info {
    background: rgba(168, 185, 255, 0.1);
    border-left-color: var(--primary-light);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="url"],
textarea {
    background-color: var(--dark-input-bg);
    border-color: var(--dark-input-border);
    color: var(--dark-text);
    caret-color: var(--primary-light);
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="url"]:focus,
textarea:focus {
    border-color: var(--primary-light);
    box-shadow: 0 0 0 3px rgba(168, 185, 255, 0.2);
    background-color: rgba(168, 185, 255, 0.08);
}

input[type="text"]:focus-visible,
input[type="email"]:focus-visible,
input[type="tel"]:focus-visible,
input[type="url"]:focus-visible,
textarea:focus-visible {
    outline: 2px solid var(--primary-light);
    outline-offset: 2px;
}

.field-error {
    background-color: rgba(255, 127, 127, 0.15);
    border-left-color: var(--error-dark);
}

input[type="text"]:invalid:not(:placeholder-shown),
input[type="email"]:invalid:not(:placeholder-shown),
input[type="tel"]:invalid:not(:placeholder-shown),
input[type="url"]:invalid:not(:placeholder-shown) {
    border-color: var(--error-dark);
}

input[type="text"]:valid:not(:placeholder-shown),
input[type="email"]:valid:not(:placeholder-shown),
input[type="tel"]:valid:not(:placeholder-shown),
input[type="url"]:valid:not(:placeholder-shown) {
    border-color: var(--success-dark);
    box-shadow: 0 0 0 3px rgba(102, 187, 106, 0.15);
}

.form-feedback {
    background: none;
    padding: 1rem;
}

.form-feedback.success {
    background-color: rgba(30, 78, 32, 0.4);
    color: #90ee90;
    border-color: rgba(102, 187, 106, 0.4);
    border-left-color: #66bb6a;
}

.form-feedback.error {
    background-color: rgba(90, 30, 30, 0.4);
    color: #ff9999;
    border-color: rgba(255, 127, 127, 0.4);
    border-left-color: #ff7f7f;
}

input::placeholder,
textarea::placeholder {
    color: #999;
    opacity: 1;
}

.field-error {
    color: var(--error-dark);
}

.message-counter {
    color: #999;
}

.field-hint {
    color: #aaa;
}

input:focus ~ .field-hint,
textarea:focus ~ .field-hint {
    color: var(--primary-light);
}

