                                throw new Error(`Request error (${response.status}). Please check your input and try again.`);
                            }
                            throw new Error(`Server error: ${response.status}`);
                        }
                        return response;
                    })
                    .then(() => {
                        feedback.className = 'form-feedback success';
                        feedback.innerHTML = '<strong>✓ Success!</strong> Thank you for your message. We will be in touch soon.';
                        feedback.setAttribute('role', 'status');
                        feedback.setAttribute('aria-live', 'polite');
                        contactForm.reset();
                        try {
                            localStorage.removeItem(FORM_STORAGE_KEY);
                        } catch (e) {
                            console.debug('Could not clear form draft');
                        }
                        inputs.forEach(input => {
                            clearError(input);
                            input.setAttribute('aria-invalid', 'false');
                        });
                        updateMessageCounter();
                        requestAnimationFrame(() => {
                            try {
                                feedback.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                                feedback.setAttribute('tabindex', '-1');
                                feedback.focus({ preventScroll: true });
                                feedback.removeAttribute('tabindex');
                            } catch (e) {
                                console.debug('Could not scroll to feedback');
                            }
                        });
                    })
                    .catch(error => {
                        feedback.className = 'form-feedback error';
                        feedback.setAttribute('role', 'alert');
                        feedback.setAttribute('aria-live', 'assertive');
                        const isDarkMode = document.documentElement.classList.contains('dark-mode');
                        if (error.name === 'AbortError') {
                            feedback.textContent = 'Request timed out. Please check your connection and try again.';
                        } else if (error instanceof TypeError) {
                            feedback.textContent = 'Connection failed. Please check your internet connection and try again.';
                        } else if (error && error.message) {
                            feedback.textContent = error.message;
                        } else {
                            feedback.textContent = 'Something went wrong. Please try again in a moment.';
                            if (typeof console !== 'undefined' && console.error) {
                                console.error('Form submission error:', error);
                            }
                        }
                    })
                    .finally(() => {
                        clearTimeout(timeoutId);
                        const elapsedTime = Date.now() - startTime;
                        const remainingDelay = Math.max(0, minLoadingDuration - elapsedTime);

                        setTimeout(() => {
                            isSubmitting = false;
                            submitBtn.disabled = false;
                            submitBtn.classList.remove('loading');
                            submitBtn.innerHTML = originalHTML;
                            submitBtn.removeAttribute('aria-busy');
                            if (originalAriaLabel) {
                                submitBtn.setAttribute('aria-label', originalAriaLabel);
                            }
                            requestAnimationFrame(() => {
                                try {
                                    feedback.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                                    if (feedback.textContent) {
                                        feedback.setAttribute('tabindex', '-1');
                                        feedback.focus({ preventScroll: true });
                                        feedback.removeAttribute('tabindex');
                                        if (!feedback.classList.contains('success')) {
                                            const firstError = contactForm.querySelector('[aria-invalid="true"]');
                                            if (firstError && firstError.focus) {
                                                setTimeout(() => firstError.focus(), 100);
                                            }
                                        }
                                    }
                                } catch (e) {
                                    console.debug('Error managing focus:', e);
                                }
                            });
                        }, remainingDelay);
                    });
                });
            }
        }
    </script>
</body>
</html>
